print "password=$pw len=", length($pw), "\n";
open my $o, ">", "/app/recovered_passwords.txt" or die $!;
print $o "$pw\n";
close $o;
' && echo "--- /app/recovered_passwords.txt ---" && cat /app/recovered_passwords.txt

